package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// fakeTSC builds a stand-in for tsc that the test controls: for every
// islands/**/*.ts it writes the .js (the source as is), a .js.map and a .d.ts
// under --outDir, and lists them the way --listEmittedFiles does. A source
// with "erro" in it fails the compilation, as a type error would.
const fakeTSCSource = `package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	var out, root string
	for i, a := range os.Args {
		switch a {
		case "--outDir":
			out = os.Args[i+1]
		case "--rootDir":
			root = os.Args[i+1]
		}
	}
	filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(p, ".ts") {
			return err
		}
		src, _ := os.ReadFile(p)
		if strings.Contains(string(src), "erro") {
			fmt.Println(p + "(1,1): error TS2322: Type 'string' is not assignable to type 'number'.")
			os.Exit(2)
		}
		rel, _ := filepath.Rel(root, p)
		base := filepath.Join(out, strings.TrimSuffix(rel, ".ts"))
		os.MkdirAll(filepath.Dir(base), 0o755)
		os.WriteFile(base+".js", append(src, "//# sourceMappingURL="+filepath.Base(base)+".js.map\n"...), 0o644)
		abs, _ := filepath.Abs(p)
		srcRel, _ := filepath.Rel(filepath.Dir(base), abs)
		os.WriteFile(base+".js.map", []byte("{\"version\":3,\"sources\":[\""+filepath.ToSlash(srcRel)+"\"],\"mappings\":\"AAAA\"}"), 0o644)
		os.WriteFile(base+".d.ts", []byte("export {};\n"), 0o644)
		for _, ext := range []string{".js", ".js.map", ".d.ts"} {
			fmt.Println("TSFILE: " + base + ext)
		}
		return nil
	})
}
`

func buildFakeTSC(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	src := filepath.Join(dir, "tsc.go")
	if err := os.WriteFile(src, []byte(fakeTSCSource), 0o644); err != nil {
		t.Fatal(err)
	}
	bin := filepath.Join(dir, "tsc")
	if runtime.GOOS == "windows" {
		bin += ".exe"
	}
	cmd := exec.Command("go", "build", "-o", bin, src)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GO111MODULE=off")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build fake tsc: %s", out)
	}
	return bin
}

func islandsProject(t *testing.T, files map[string]string) *project {
	t.Helper()
	root := t.TempDir()
	for name, body := range files {
		p := filepath.Join(root, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	return &project{Root: root}
}

func read(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// The build writes into public/ what tsc emitted, every .js and .d.ts with the
// banner that names its source, and the source map shifted by the banner line.
func TestIslandsBuildWritesAndMarks(t *testing.T) {
	t.Setenv("TRILHA_TSC", buildFakeTSC(t))
	p := islandsProject(t, map[string]string{
		"islands/tsconfig.json":  `{}`,
		"islands/jogo/motor.ts":  "export const passo = 1;\n",
		"islands/jogo/island.ts": "import { passo } from \"./motor.js\";\n",
		"public/estilo.css":      "body{}",
	})
	files, err := buildIslands(p.Root, filepath.Join(p.Root, "public"), filepath.Join(p.Root, "public"))
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != 6 {
		t.Fatalf("esperava 6 arquivos (2 × js, map, d.ts): %v", files)
	}
	js := read(t, filepath.Join(p.Root, "public/jogo/motor.js"))
	if !strings.HasPrefix(js, "// Code generated by trilha islands build from islands/jogo/motor.ts. DO NOT EDIT.\nexport const passo") {
		t.Fatalf("sem o banner certo:\n%s", js)
	}
	if dts := read(t, filepath.Join(p.Root, "public/jogo/motor.d.ts")); !strings.HasPrefix(dts, islandsBanner) {
		t.Fatalf("d.ts sem banner:\n%s", dts)
	}
	m := read(t, filepath.Join(p.Root, "public/jogo/motor.js.map"))
	if !strings.Contains(m, `"mappings":";AAAA"`) {
		t.Fatalf("o mapa não andou uma linha com o banner: %s", m)
	}
	if !strings.Contains(m, `"sources":["../../islands/jogo/motor.ts"]`) {
		t.Fatalf("a fonte do mapa tem que ser relativa a public/: %s", m)
	}
	if css := read(t, filepath.Join(p.Root, "public/estilo.css")); css != "body{}" {
		t.Fatalf("o build mexeu no que não é dele: %q", css)
	}
}

// --check compiles elsewhere and compares: fresh passes; an edited output, a
// missing one and an orphan of a deleted source fail, each named.
func TestIslandsBuildCheck(t *testing.T) {
	t.Setenv("TRILHA_TSC", buildFakeTSC(t))
	p := islandsProject(t, map[string]string{
		"islands/tsconfig.json":  `{}`,
		"islands/jogo/motor.ts":  "export const passo = 1;\n",
		"islands/jogo/island.ts": "export default {};\n",
		"public/manual.js":       "// escrito à mão, não é do build\n",
	})
	public := filepath.Join(p.Root, "public")
	if _, err := buildIslands(p.Root, public, public); err != nil {
		t.Fatal(err)
	}
	if probs, err := checkIslandsBuild(p.Root); err != nil || len(probs) != 0 {
		t.Fatalf("recém-compilado tem que passar: %v %v", probs, err)
	}
	if status, _ := checkStepIslands(p, false); status != statusOK {
		t.Fatalf("passo do check: %s", status)
	}

	// Someone edits the output by hand, and a source goes away.
	os.WriteFile(filepath.Join(public, "jogo/motor.js"), []byte("// mexido\n"), 0o644)
	os.Remove(filepath.Join(p.Root, "islands/jogo/island.ts"))
	os.Remove(filepath.Join(public, "jogo/motor.d.ts"))
	probs, err := checkIslandsBuild(p.Root)
	if err != nil {
		t.Fatal(err)
	}
	got := strings.Join(probs, "\n")
	for _, want := range []string{
		"public/jogo/motor.js: differs",
		"public/jogo/motor.d.ts: islands build would write it",
		"public/jogo/island.js: generated by islands build, but its source is gone",
		"public/jogo/island.d.ts: generated by islands build",
	} {
		if !strings.Contains(got, want) {
			t.Fatalf("faltou %q em:\n%s", want, got)
		}
	}
	if strings.Contains(got, "manual.js") {
		t.Fatalf("arquivo sem banner não é do build:\n%s", got)
	}
	if status, list := checkStepIslands(p, false); status != statusFailed || len(list) != len(probs) {
		t.Fatalf("passo do check: %s %+v", status, list)
	}
}

// Without islands/tsconfig.json the gate does not run; a type error fails it
// with the compiler's own message; and with no compiler it says how to get one.
func TestIslandsBuildGate(t *testing.T) {
	if status, _ := checkStepIslands(islandsProject(t, map[string]string{"public/a.js": ""}), false); status != statusSkipped {
		t.Fatalf("sem tsconfig: %s", status)
	}

	t.Setenv("TRILHA_TSC", buildFakeTSC(t))
	quebrado := islandsProject(t, map[string]string{
		"islands/tsconfig.json": `{}`,
		"islands/a.ts":          "const n: number = 'erro';\n",
	})
	status, probs := checkStepIslands(quebrado, false)
	if status != statusFailed || len(probs) != 1 || !strings.Contains(probs[0].Message, "TS2322") {
		t.Fatalf("erro de tipo tem que reprovar com a mensagem do tsc: %s %+v", status, probs)
	}

	t.Setenv("TRILHA_TSC", "")
	t.Setenv("PATH", t.TempDir())
	semTSC := islandsProject(t, map[string]string{"islands/tsconfig.json": `{}`})
	if _, err := buildIslands(semTSC.Root, filepath.Join(semTSC.Root, "public"), filepath.Join(semTSC.Root, "public")); err == nil || !strings.Contains(err.Error(), "TRILHA_TSC") {
		t.Fatalf("sem tsc: %v", err)
	}
	// node_modules/.bin/tsc wins over the PATH when there is one.
	local := filepath.Join(semTSC.Root, "node_modules", ".bin", "tsc")
	if runtime.GOOS == "windows" {
		local += ".cmd"
	}
	os.MkdirAll(filepath.Dir(local), 0o755)
	os.WriteFile(local, []byte("#!/bin/sh\n"), 0o755)
	if got, err := findTSC(semTSC.Root); err != nil || got != local {
		t.Fatalf("findTSC = %q %v", got, err)
	}
}
